SELECT COALESCE((SELECT SUM(p.amount_bdt) FROM payments p WHERE p.status = 'captured' AND p.order_id IN (SELECT o.order_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-10-01 00:00:00' AND o.order_at < TIMESTAMP '2025-11-01 00:00:00')), 0) - COALESCE((SELECT SUM(r.amount_bdt) FROM refunds r WHERE r.order_id IN (SELECT o.order_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-10-01 00:00:00' AND o.order_at < TIMESTAMP '2025-11-01 00:00:00')), 0) AS v
